command.css:
html, body, .khonsera-app, .khonsera-app--unified {
  background:#050505 !important;
  color:#f7f7f4 !important;
}
.khonsera-app:has(.cc-today-direction) {
  --today-ground:#050505 !important;
  --today-chrome:#050505 !important;
  --today-surface:#111111 !important;
  --today-surface-muted:#1a1a1a !important;
  --today-paper:#f4f4f0 !important;
  --today-ink:#f7f7f4 !important;
  --today-ink-2:#deded8 !important;
  --today-muted:#969690 !important;
  --today-faint:#666662 !important;
  --today-border:#2b2b2b !important;
  --today-border-strong:#3b3b3b !important;
  --today-green:#f4f4f0 !important;
  --today-green-strong:#ffffff !important;
  --today-green-soft:#202020 !important;
  --today-orange:#ffffff !important;
  --today-orange-strong:#ffffff !important;
  --today-orange-soft:#202020 !important;
  --today-danger:#ffffff !important;
  --today-danger-soft:#252525 !important;
  --today-radius-card:14px !important;
  --today-radius-compact:12px !important;
  --today-radius-control:9px !important;
  --today-shadow-card:none !important;
  background:#050505 !important;
}
.khonsera-app:has(.cc-today-direction) .cc-app-main {
  background:#050505 !important;
  padding:8px 8px 88px !important;
}
.khonsera-app:has(.cc-today-direction) .cc-appbar {
  min-height:62px !important;
  border-bottom:1px solid #1d1d1d !important;
  background:#050505 !important;
  backdrop-filter:none !important;
}
.khonsera-app:has(.cc-today-direction) .cc-lockup,
.khonsera-app:has(.cc-today-direction) .cc-iconbtn {
  color:#f7f7f4 !important;
}
.khonsera-app:has(.cc-today-direction) .cc-brand-dot {
  width:5px !important;
  height:5px !important;
  background:#f7f7f4 !important;
  box-shadow:none !important;
}
.khonsera-app:has(.cc-today-direction) .cc-iconbtn {
  border:1px solid #292929 !important;
  border-radius:12px !important;
  background:#101010 !important;
  box-shadow:none !important;
}
.khonsera-app .cc-today-direction {
  width:100% !important;
  margin:0 !important;
  padding:14px !important;
  gap:12px !important;
  border:1px solid #d8d8d2 !important;
  border-radius:24px !important;
  background:#f4f4f0 !important;
  color:#111111 !important;
}
.khonsera-app .cc-today-direction > .cc-screen-content {
  gap:10px !important;
}
.khonsera-app .cc-today-head {
  grid-template-columns:minmax(0,1fr) 96px !important;
  gap:10px !important;
  padding:2px 0 12px !important;
  border-bottom:1px solid #cfcfc9 !important;
}
.khonsera-app .cc-today-head::before {
  display:none !important;
}
.khonsera-app .cc-today-head .cc-eyebrow {
  color:#777773 !important;
  font-size:7px !important;
  letter-spacing:.17em !important;
}
.khonsera-app .cc-today-head .cc-screen-title {
  margin-top:4px !important;
  color:#0b0b0b !important;
  font-size:38px !important;
  font-weight:650 !important;
  letter-spacing:-.055em !important;
}
.khonsera-app .cc-today-head .cc-screen-description,
.khonsera-app .cc-today-destination {
  color:#5d5d59 !important;
  font-size:10px !important;
}
.khonsera-app .cc-today-direction .cc-weather {
  width:96px !important;
  min-width:96px !important;
  min-height:54px !important;
  padding:9px 10px !important;
  border:0 !important;
  border-radius:13px !important;
  background:#101010 !important;
  color:#fff !important;
  box-shadow:none !important;
}
.khonsera-app .cc-today-direction .cc-weather-glyph,
.khonsera-app .cc-today-direction .cc-weather-temp,
.khonsera-app .cc-today-direction .cc-weather-headline {
  color:#f7f7f4 !important;
}
.khonsera-app .cc-day-forecast {
  overflow:hidden !important;
  border:1px solid #d4d4ce !important;
  border-radius:13px !important;
  background:#e7e7e2 !important;
}
.khonsera-app .cc-weather-hours {
  gap:1px !important;
  background:#cfcfca !important;
}
.khonsera-app .cc-weather-hour {
  min-width:58px !important;
  padding:8px 6px !important;
  background:#f4f4f0 !important;
}
.khonsera-app .cc-weather-hour-time,
.khonsera-app .cc-weather-hour-temp,
.khonsera-app .cc-weather-hour-glyph {
  color:#111 !important;
}
.khonsera-app .cc-today-command .cc-active-tile {
  gap:11px !important;
  padding:15px !important;
  border:0 !important;
  border-radius:16px !important;
  background:#101010 !important;
  color:#f7f7f4 !important;
  box-shadow:none !important;
}
.khonsera-app .cc-today-command .cc-active-tile::before {
  display:none !important;
}
.khonsera-app .cc-today-command .cc-at-status,
.khonsera-app .cc-today-command .cc-setoff-kicker,
.khonsera-app .cc-today-command .cc-setoff-for,
.khonsera-app .cc-today-command .cc-setoff-move {
  color:#a5a5a0 !important;
}
.khonsera-app .cc-today-command .cc-at-dot {
  width:5px !important;
  height:5px !important;
  border-radius:50% !important;
  background:#f7f7f4 !important;
}
.khonsera-app .cc-today-command .cc-next-priority {
  border:1px solid #3a3a3a !important;
  border-radius:8px !important;
  background:#1c1c1c !important;
  color:#d8d8d2 !important;
}
.khonsera-app .cc-today-command :is(.cc-setoff-figure,.cc-setoff-figure--word) {
  color:#ffffff !important;
  font-family:var(--mono) !important;
  font-size:54px !important;
  font-weight:540 !important;
  letter-spacing:-.075em !important;
}
.khonsera-app .cc-today-command .cc-setoff-colon {
  color:#777 !important;
}
.khonsera-app .cc-today-command .cc-leave-ring {
  border:1px solid #333 !important;
  border-radius:10px !important;
  background:#1a1a1a !important;
}
.khonsera-app .cc-today-command .cc-leave-ring > span {
  color:#8d8d88 !important;
}
.khonsera-app .cc-today-command .cc-leave-ring strong {
  color:#fff !important;
}
.khonsera-app .cc-today-command .cc-next-facts > span {
  border:1px solid #333 !important;
  border-radius:8px !important;
  background:#181818 !important;
  color:#d7d7d2 !important;
}
.khonsera-app .cc-today-command .cc-next-facts svg {
  color:#f7f7f4 !important;
}
.khonsera-app .cc-today-command .cc-next-action {
  border:1px solid #333 !important;
  border-radius:10px !important;
  background:#181818 !important;
  color:#dcdcd7 !important;
}
.khonsera-app .cc-today-command .cc-next-action--primary {
  border-color:#f4f4f0 !important;
  background:#f4f4f0 !important;
  color:#0b0b0b !important;
  box-shadow:none !important;
}
.khonsera-app .kh-itinerary-head {
  min-height:40px !important;
  margin-bottom:8px !important;
  padding-bottom:8px !important;
  border-bottom:1px solid #cfcfc9 !important;
}
.khonsera-app .kh-itinerary-title,
.khonsera-app .kh-itinerary-count {
  color:#111 !important;
}
.khonsera-app .kh-itinerary-title {
  font-size:15px !important;
  text-transform:uppercase !important;
  letter-spacing:.02em !important;
}
.khonsera-app .kh-spine-rail {
  left:13px !important;
  background:#b7b7b2 !important;
}
.khonsera-app .kh-spine-marker {
  width:26px !important;
  height:26px !important;
  min-width:26px !important;
  border:1px solid #1e1e1e !important;
  border-radius:7px !important;
  background:#111 !important;
  color:#fff !important;
  box-shadow:none !important;
}
.khonsera-app .kh-spine-marker[data-kind],
.khonsera-app .kh-spine-marker[data-active="true"] {
  border-color:#111 !important;
  background:#111 !important;
  color:#fff !important;
}
.khonsera-app :is(.kh-movement-card,.kh-hub-card,.kh-station-card,.kh-change-card,.kh-appointment-card) {
  border:0 !important;
  border-radius:14px !important;
  background:#111 !important;
  color:#f7f7f4 !important;
  box-shadow:none !important;
}
.khonsera-app :is(.kh-movement-card,.kh-hub-card,.kh-station-card,.kh-change-card,.kh-appointment-card)::before {
  display:none !important;
}
.khonsera-app :is(.kh-card-eyebrow,.kh-movement-duration,.kh-movement-times time,.kh-movement-destination,.kh-station-card header time,.kh-station-title,.kh-station-dwell,.kh-hub-copy strong,.kh-hub-times strong,.kh-change-main strong,.kh-change-duration strong) {
  color:#f4f4ef !important;
}
.khonsera-app :is(.kh-mode-tag,.kh-buffer-chip) {
  border:1px solid #343434 !important;
  border-radius:7px !important;
  background:#1d1d1d !important;
  color:#d8d8d2 !important;
}
.khonsera-app :is(.kh-movement-rule,.kh-spine-toggle) {
  border-color:#343434 !important;
  background:#202020 !important;
  color:#b0b0ab !important;
}
.khonsera-app .kh-movement-rule {
  background:#343434 !important;
}
.khonsera-app :is(.kh-hub-times,.kh-change-times) small,
.khonsera-app .kh-change-duration span {
  color:#777772 !important;
}
.khonsera-app .kh-time-arrow {
  color:#9b9b96 !important;
}
.khonsera-app .cc-tabbar-wrap {
  border-top:1px solid #1d1d1d !important;
  background:#050505 !important;
  box-shadow:none !important;
  backdrop-filter:none !important;
}
.khonsera-app .cc-tab {
  color:#747474 !important;
  border-radius:10px !important;
}
.khonsera-app .cc-tab[data-active="true"] {
  background:#f4f4f0 !important;
  color:#0b0b0b !important;
}
.khonsera-app .cc-tab[data-active="true"] :is(.cc-tab-ico,.cc-tab-label) {
  color:#0b0b0b !important;
}
